import{linear,inverseLinear,rotate,determinant,midpointSquare,geometricSum,mean,median,choose,modulo,graphEdges,shortestPath}from'./extended-math.js';
export const c=(id,label,min,max,step,value,unit='')=>({id,label,min,max,step,value,unit});
export const lesson=(id,name,concept,field,color,question,invitation,controls,intuition,math,why,q,options,correct,explain,related,feedback)=>({id,name,concept,field,color,question,invitation,controls,intuition,math:'<span class="formula">'+math+'</span>',why,challenge:{q,options,correct,explain},related,feedback,symbol:'✧',caption:invitation});
export const extendedDiscoveries=[
lesson('functions','The Rule Engine','Linear functions','ALGEBRA','#99e2da','What happens when you change the rule?','Change the slope or shift. Move the input point along the line.',[c('a','Slope a',-3,3,.1,1),c('b','Vertical shift b',-3,3,.1,1),c('x','Input x',-2,2,.1,1)],'A function assigns one output to each input. This line uses the rule y = ax + b. Slope controls the change per step; b controls the output at zero.','y = ax + b','Increasing x by one changes ax+b by a. Setting x=0 gives b. These two facts explain the slope and the vertical intercept of every line in this family.','If a = 0, what happens when x changes?',['The output stays at b','The output doubles','The line becomes vertical'],0,'With a = 0, the expression is y = b for every x.','inverse',v=>`Input ${v.x.toFixed(1)} gives output ${linear(v.x,v.a,v.b).toFixed(2)}. Each extra input unit changes the output by ${v.a.toFixed(1)}.`),
lesson('inverse','The Return Signal','Inverse functions','ALGEBRA','#b4ccf8','Can you undo a rule?','The original rule is blue. Its inverse is amber. Change the rule and input.',[c('a','Multiplier a',.5,3,.1,2),c('b','Shift b',-2,2,.1,1),c('x','Original input',-2,2,.1,1)],'An inverse reverses the input-output relationship. Feed an input into the original rule, then feed its output into the inverse. You get your starting value back.','f⁻¹(y) = (y − b) / a','Solving y=ax+b for x gives (y-b)/a, provided a is nonzero. Swapping input and output reflects the graph across y=x. The positive nonzero multipliers here guarantee a unique inverse.','Which operation undoes f(x) = 2x + 3?',['Multiply by 2, then add 3','Subtract 3, then divide by 2','Divide by 2, then subtract 3'],1,'Undo the operations in reverse order: subtract 3 before dividing by 2.','functions',v=>{const out=linear(v.x,v.a,v.b);return`${v.x.toFixed(1)} becomes ${out.toFixed(2)}, then the inverse returns ${inverseLinear(out,v.a,v.b).toFixed(2)}. A round trip with no baggage lost.`}),
lesson('exponential','The Multiplying Light','Exponential growth','ALGEBRA','#eec27e','What happens when growth grows?','Change the multiplier and the number of rounds.',[c('r','Multiplier per round',1.1,3,.1,2),c('n','Number of rounds',0,8,1,4)],'Linear growth adds a fixed amount. Exponential growth multiplies by a fixed factor. The same percentage increase creates larger absolute jumps as the starting amount grows.','N(n) = rⁿ','Starting with one, multiply by r at each step. After n steps, the product has n factors of r. A fractional value is a mathematical quantity, not necessarily a count of physical objects.','Starting from one, how much remains after five doublings?',['10','25','32'],2,'The product is 2 × 2 × 2 × 2 × 2 = 32.','limits',v=>`${v.n} rounds at ×${v.r.toFixed(1)} give ${(v.r**v.n).toFixed(2)}. The last round adds ${(v.n?v.r**v.n-v.r**(v.n-1):0).toFixed(2)}.`),
lesson('unitcircle','The Circular Signal','Sine & cosine','TRIGONOMETRY','#88dacc','How does a circle become a wave?','Move the angle. The horizontal and vertical projections follow the orbit.',[c('angle','Angle around the circle',0,360,1,45,'°')],'On a circle of radius one, cosine is the horizontal coordinate and sine is the vertical coordinate. The rotating point connects angles to two signed lengths.','(x, y) = (cos θ, sin θ)','The distance from the origin is one. Applying the Pythagorean theorem to the projections gives cos²θ + sin²θ = 1. Signs depend on the quadrant. Angles in the control are degrees.','At 90°, which pair is (cos θ, sin θ)?',['(1, 0)','(0, 1)','(−1, 0)'],1,'At a quarter turn, the point is at the top of the unit circle.','waves',v=>{const t=v.angle*Math.PI/180;return`At ${v.angle}°, horizontal = ${Math.cos(t).toFixed(3)} and vertical = ${Math.sin(t).toFixed(3)}. Both are coordinates, not distances travelled.`}),
lesson('integrals','The Accumulation Sea','Integrals','CALCULUS','#efbc8a','Can small pieces measure a whole?','Increase the number of rectangles under y = x².',[c('end','Right endpoint',.5,3,.1,2),c('n','Midpoint rectangles',1,60,1,8)],'Each rectangle estimates a small strip of area. Adding them estimates the whole region. Narrower strips follow the curve more closely.','∫₀ᵇ x² dx = b³ / 3','The derivative of x³/3 is x². The fundamental theorem of calculus evaluates the exact area as b³/3. Midpoint rectangles converge as their widths shrink; the drawn rectangles are an approximation, not the definition of exact equality.','What is the exact area under x² from 0 to 3?',['3','9','27'],1,'Evaluate x³/3 at 3 and subtract its value at 0: 27/3 = 9.','derivatives',v=>`Rectangles: ${midpointSquare(v.end,v.n).toFixed(4)}. Exact area: ${(v.end**3/3).toFixed(4)}. Error: ${(v.end**3/3-midpointSquare(v.end,v.n)).toFixed(4)}.`),
lesson('limits','The Never-Ending Sum','Geometric series & limits','CALCULUS','#c7b5ed','Can infinitely many pieces fit in a finite space?','Add terms and change the fraction retained at each step.',[c('r','Ratio r',.2,.85,.05,.5),c('n','Terms included',1,30,1,6)],'Start with 1, then add r, r², and so on. Each new piece is smaller when 0 < r < 1. The partial sum approaches a finite total.','1 + r + r² + … = 1 / (1 − r)','For n terms, Sₙ=(1-rⁿ)/(1-r). This follows by subtracting rSₙ from Sₙ. Because |r|<1, rⁿ tends to zero, giving the infinite sum. The screen always draws finitely many terms.','What does 1 + 1/2 + 1/4 + … approach?',['1','2','Infinity'],1,'The sum is 1/(1−1/2)=2, although no finite partial sum equals 2.','exponential',v=>`${v.n} terms sum to ${geometricSum(v.r,v.n).toFixed(4)}. The limit is ${(1/(1-v.r)).toFixed(4)}. Remaining gap: ${(v.r**v.n/(1-v.r)).toFixed(5)}.`),
lesson('rotation','The Turning Space','Rotation matrices','GEOMETRY','#a6d5fb','What changes when the world turns?','Rotate the triangle around the origin. Its original outline remains visible.',[c('angle','Rotation angle',-180,180,1,40,'°')],'A rotation moves every point through the same angle around the origin. Position changes, but lengths, angles, and area stay the same.','Rθ = [ cos θ, −sin θ ; sin θ, cos θ ]','The columns are the rotated unit-axis vectors. They remain perpendicular and have length one, so the transformation preserves dot products and therefore lengths and angles.','A 90° counterclockwise rotation sends (1, 0) to…',['(0, 1)','(0, −1)','(1, 1)'],0,'The positive horizontal unit vector turns to the positive vertical axis.','determinant',v=>{const p=rotate(2,1,v.angle);return`The vertex (2, 1) moves to (${p[0].toFixed(2)}, ${p[1].toFixed(2)}). Its distance from the origin stays √5.`}),
lesson('determinant','The Area Engine','Determinants','LINEAR ALGEBRA','#9cc6ec','Can a transformation flatten space?','Change the vertical stretch. Watch the unit square become a parallelogram.',[c('k','Vertical stretch k',-2,2,.1,1),c('shear','Horizontal shear',-2,2,.1,.6)],'A determinant measures signed area scaling. Zero collapses the square to a line. A negative value reverses orientation; its absolute value still gives area scaling.','det [ 1, s ; 0, k ] = k','The transformed basis vectors are (1,0) and (s,k). The parallelogram has base one and height |k|. The sign records orientation. A shear changes its slant without changing this area.','What does a zero determinant mean here?',['The area doubles','The square collapses to a line','The square only rotates'],1,'At k=0, both transformed basis vectors lie on the same line.','vectors',v=>`Determinant = ${v.k.toFixed(1)}. Area = ${Math.abs(v.k).toFixed(1)}. ${v.k<0?'Orientation is reversed.':v.k===0?'Two dimensions have collapsed into one.':'Orientation is preserved.'}`),
lesson('mean','The Outlier Observatory','Mean & median','PROBABILITY','#f0abc5','Can one observation move the whole average?','Move the final observation and compare the two centers.',[c('outlier','Last observation',1,30,1,12)],'The mean shares the total equally among all observations. The median is the middle of the sorted data. A distant observation can pull the mean much farther than the median.','Mean = Σx / n','For six sorted values, the median is the average of the third and fourth. Increasing one observation by Δ changes the mean by Δ/6. The median changes only when the central order positions change.','What happens to the mean if one of six observations increases by 6?',['It increases by 1','It increases by 6','It stays the same'],0,'The total rises by 6, and the number of observations remains 6.','probability',v=>{const xs=[2,3,4,5,6,v.outlier];return`Data: ${xs.join(', ')}. Mean ${mean(xs).toFixed(2)}; median ${median(xs).toFixed(2)}. One dramatic observation, two different reactions.`}),
lesson('combinations','The Selection Cluster','Combinations','PROBABILITY','#d9acef','How many groups can you choose?','Choose a group size. Each row is one possible selection.',[c('n','Available objects',4,8,1,5),c('k','Objects to choose',0,4,1,2)],'A combination chooses a group without caring about order. Choosing A then B is the same group as choosing B then A.','C(n,k) = n! / [k!(n−k)!]','Ordered selections count n(n−1)…(n−k+1) possibilities. Each unordered group appears in k! orders, so divide by k!. Choosing zero objects gives one group: the empty selection.','How many pairs can be selected from five objects?',['5','10','20'],1,'There are 5×4 ordered pairs; dividing by 2 removes the repeated ordering, giving 10.','graphs',v=>`${choose(v.n,v.k)} distinct groups choose ${v.k} from ${v.n}. ${v.k===0?'The empty selection counts as one.':'Changing the order does not create a new group.'}`),
lesson('graphs','The Route Constellation','Shortest paths','DISCRETE MATH','#c9dba1','Is the fewest-hop route always the shortest?','Change the cost of the B–E connection. Find the cheapest route from A to E.',[c('cost','B–E connection cost',1,12,1,2)],'A graph models connections. A weighted shortest path minimizes total edge cost, which can mean distance, time, or effort. The number of steps is a different measure.','Path cost = sum of its edge weights','For nonnegative weights, Dijkstra’s algorithm repeatedly finalizes the nearest unsettled vertex. Any alternative through a more distant unsettled vertex cannot make that finalized distance smaller. All edges here can be travelled in either direction.','If B–E costs 9, which route from A to E is cheapest?',['A–B–E','A–D–E','A–B–C–E'],1,'A–D–E costs 6+2=8; the alternatives cost 12 and 10.','combinations',v=>{const r=shortestPath(graphEdges(v.cost),'A','E');return`Cheapest route: ${r.path.join(' – ')}. Total cost ${r.distance}. Connections, not screen distances, determine the result.`}),
lesson('modular','The Clock Asteroid','Modular arithmetic','DISCRETE MATH','#e9b77f','Where do numbers go after a full turn?','Change the number and the size of the clock.',[c('n','Clock size',2,12,1,7),c('value','Number of steps',0,36,1,17)],'Modular arithmetic keeps the remainder after division. A clock wraps around after a fixed number of steps, so different numbers can land at the same position.','a = qn + r, with 0 ≤ r < n','Euclidean division uniquely separates a nonnegative integer into whole groups of n plus a remainder. Numbers differing by a multiple of n have the same remainder. This clock starts at zero.','On a clock of size 7, where does 17 land?',['2','3','4'],1,'17 = 2×7+3, so the remainder is 3.','unitcircle',v=>`${v.value} = ${Math.floor(v.value/v.n)} × ${v.n} + ${modulo(v.value,v.n)}. ${Math.floor(v.value/v.n)} full turns, then ${modulo(v.value,v.n)} extra steps.`),
lesson('symmetry','The Repeating Shape','Rotational symmetry','GEOMETRY','#b1d996','When does a turn leave a shape unchanged?','Rotate the regular polygon. Compare it with the original outline.',[c('n','Number of sides',3,10,1,5),c('angle','Rotation angle',0,360,1,72,'°')],'A regular polygon returns to the same outline several times during a full turn. These matching rotations are its rotational symmetries.','Smallest matching turn = 360° / n','The vertices are equally spaced around the circle. A rotation through 360°/n moves every vertex to the next vertex and preserves the edges. Its multiples give all n distinct rotations, counting the identity.','What is the smallest positive matching turn of a regular hexagon?',['30°','60°','120°'],1,'A hexagon has six equally spaced vertices: 360°/6=60°.','rotation',v=>{const step=360/v.n,gap=Math.abs(v.angle/step-Math.round(v.angle/step));return`A ${v.n}-sided regular polygon matches every ${step.toFixed(2)}°. ${gap<.001?'The outlines coincide.':'Keep turning to align the outlines.'}`})
];
